    if (!newActTitle.trim()) return;
    const costNum = parseInt(newActCost, 10) || 0;
    const newAct: Activity = {
      id: `act-${Date.now()}`,
      timeSlot: 'AFTERNOON',
      timeRange: newActTime || '14:00–15:30',
